const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const clinic_name = text(input.clinic_name);
const doctor_name = text(input.doctor_name);
const service_name = text(input.service_name);
const target_date = text(input.target_date);

const parsedLimit = Number(input.limit ?? 5);
const limit = Number.isInteger(parsedLimit) ? parsedLimit : 5;

const errors = [];

if (!clinic_name) {
  errors.push({ field: 'clinic_name', message: 'نام کلینیک الزامی است.' });
}

if (!doctor_name) {
  errors.push({ field: 'doctor_name', message: 'نام پزشک الزامی است.' });
}

if (!service_name) {
  errors.push({ field: 'service_name', message: 'نام خدمت الزامی است.' });
}

if (!target_date) {
  errors.push({ field: 'target_date', message: 'تاریخ موردنظر الزامی است.' });
}

function isRealIsoDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;

  const [year, month, day] = value.split('-').map(Number);
  const parsed = new Date(Date.UTC(year, month - 1, day));

  return (
    parsed.getUTCFullYear() === year &&
    parsed.getUTCMonth() === month - 1 &&
    parsed.getUTCDate() === day
  );
}

if (target_date && !isRealIsoDate(target_date)) {
  errors.push({
    field: 'target_date',
    message: 'تاریخ باید معتبر و با قالب YYYY-MM-DD باشد.',
  });
}

if (limit < 1 || limit > 20) {
  errors.push({
    field: 'limit',
    message: 'limit باید یک عدد صحیح بین 1 و 20 باشد.',
  });
}

return [
  {
    json: {
      clinic_name,
      doctor_name,
      service_name,
      target_date,
      limit,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات درخواست ناقص یا نامعتبر است.',
      slot_count: 0,
      slots: [],
      errors: $json.errors ?? [],
    },
  },
];
